from guide_utils import *
from check_math import mesh,rowcolor,tri
import json,itertools
R=Path(__file__).parent;D=json.loads((R/'math-checks.json').read_text())
COL={'R':colors.HexColor('#f7dedd'),'B':colors.HexColor('#dceafa'),'Y':colors.HexColor('#fff4c0')}
def board(c,n,row,x,y,width=220,fan=None,nums=True,door=False,highlight=True):
 vs,xy,ts=mesh(n,fan is not None);co=rowcolor(row) if row else {}
 if fan is not None:co.update({(10,k):v for k,v in enumerate(fan)})
 scale=width/n;pt={v:(x+a*scale,y+b*scale) for v,(a,b) in xy.items()}
 if co and highlight:
  for k,t in enumerate(ts,1):
   if set(co[v] for v in t)==set('RBY'):
    p=c.beginPath();p.moveTo(*pt[t[0]]);p.lineTo(*pt[t[1]]);p.lineTo(*pt[t[2]]);p.close();c.setFillColor(colors.HexColor('#edf0f1'));c.drawPath(p,fill=1,stroke=0)
 c.setStrokeColor(colors.black);c.setFillColor(colors.black);c.setLineWidth(.7)
 edges=sorted({tuple(sorted(e)) for t in ts for e in itertools.combinations(t,2)})
 for a,b in edges:
  c.line(*pt[a],*pt[b])
  if door and co and set([co[a],co[b]])==set('RB'):
   xa,ya=pt[a];xb,yb=pt[b];dx,dy=xb-xa,yb-ya;ll=math.hypot(dx,dy);mx,my=(xa+xb)/2,(ya+yb)/2;c.setLineWidth(2.5);c.setStrokeColor(colors.HexColor('#225b7a'));c.line(mx-4*dy/ll,my+4*dx/ll,mx+4*dy/ll,my-4*dx/ll);c.setLineWidth(.7);c.setStrokeColor(colors.black)
 if nums:
  for k,t in enumerate(ts,1):
   xx=sum(pt[v][0] for v in t)/3;yy=sum(pt[v][1] for v in t)/3;c.setFillColor(colors.HexColor('#5b6063'));label(c,xx-3,yy-3,str(k),8)
 for v,(xx,yy) in pt.items():
  lab=co.get(v,'');c.setFillColor(COL.get(lab,colors.white));c.circle(xx,yy,6 if width>150 else 4.5,fill=1);c.setFillColor(colors.black)
  if lab:label(c,xx-3,yy-3,lab,8 if width>150 else 6.5,True)
 c.setFillColor(colors.black)
def fig(n,row,width=255,height=None,fan=None,nums=True,door=False):
 h=height or width*math.sqrt(3)/2+28
 return Figure(522,h,lambda c,w,hh:board(c,n,row,(522-width)/2,14,width,fan,nums,door))
def pairfig(items,height=170,width=160):
 def dr(c,w,h):
  for i,(n,row,caption,fan) in enumerate(items):
   x=20+i*(522/len(items));label(c,x,h-14,caption,9,True);board(c,n,row,x+12,15,width,fan)
 return Figure(522,height,dr)
s=[T('Three-color triangles facilitator guide'),P('Library slot 16. Separate adult guide for final F16-K-v2, F16-23-v2 and F16-45-v2. Each band has Problems 1-6. K-1 has 6 pages; each older packet has 7 pages because Problem 1 is repeated on a second recording board. Draft and unpiloted; the slot number does not set a meeting calendar.'),H('The mathematical destination'),P('Labels live on vertices. Boundary restrictions force an odd number of little triangles with all three labels. R-B edges, called doors, convert this guarantee into a finite path and pairing argument. An individual outside entrance can return outside; the odd number of entrances guarantees that at least one reaches an all-three cell.'),table([['Entry','Prerequisites and useful endpoint'],['K-1','Follow spoken side rules, place lettered counters and recognize a three-label set. No reading or arithmetic beyond small counts. Find a maximum or move one all-three cell.'],['Grades 2-3','Read R/B/Y, trace edges and pair objects as odd/even. Reach local door classification and a reason zero is impossible.'],['Grades 4-5','Track complete cases, paths and odd/even. Reach the general parity proof and test the importance of its boundary hypothesis. No fixed-point theory is needed.']],[96,426]),H('Prepare for ten children'),P('Print selected pages single-sided on US Letter at 100%. Provide ten sets of three colored pencils, graphite pencils/erasers and at least 20 spare sheets. For the three youngest children, prepare three counter sets, each with 15 R, 15 B and 15 Y counters: 135 total, about 0.4 inch across. These are preparation targets, not verified inventory. Put letters or distinct symbols on every counter; do not rely on color. The largest youngest board has 15 vertices and the tightest spacing is 1.3125 inches, so test counter clearance on a printout.'),P('Keep three stable adult-led tables and choose by readiness. Keep corners fixed; enforce the permitted pair on the entire outside side. Leave cell interiors and edge midpoints clear for tracing. A little triangle is a cell with no subdivision inside it; larger triangles spanning several cells do not count. The fan board has four extra vertices inside the four original cells, and 12 little cells.'),P('Before teaching, label a board, count only its little cells and trace an R-B door route. Give older children the two Problem 1 copies to preserve a minimum and maximum. Use pencil changes or movable counters before asking for a general argument.'),PageBreak()]
s += [H('Flexible one-hour menu'),table([['Minutes','Use'],['0-4','Handle counters or color a practice triangle before introducing restrictions.'],['4-8','Shared launch below.'],['8-25','K-1 P1-P3; middle P1-P2; upper P1-P2. Let the search last.'],['25-28','Stand, switch between R and B gestures and notice when the end matches the start.'],['28-50','Choose a route: K-1 P4 or P5/P6; middle P3-P4 then P5 or P6; upper P3-P5 or the boundary exception P6.'],['50-60','Share one surprising filling and one reason. No band must finish every page.']],[64,458]),H('Shared launch'),P('On a large two-step board, place the three fixed corner counters and let children fill the remaining vertices legally. Point to a little triangle and check its three vertex labels. Change one counter without coloring the face. Ask, “Can you move an all-three triangle somewhere else?” Demonstrate the side restrictions with one illegal counter and have children repair it. Save the theorem and door technique for after experimentation.'),H('K-1 Problem 1'),P('Each of the four positions can contain the unique all-three cell, one at a time. The four fillings below are exact witnesses. All eight legal two-step fillings have exactly one; the request is sequential, not to make all four work simultaneously. Hint: keep the target triangle’s needed labels and repair the remaining boundary vertices.'),pairfig([(2,D['2']['sole']['1'],'Cell 1',None),(2,D['2']['sole']['2'],'Cell 2',None),(2,D['2']['sole']['3'],'Cell 3',None),(2,D['2']['sole']['4'],'Cell 4',None)],140,96),P('In guide diagrams, small gray numbers name cells; light shading marks the all-three cells. Letters, not shading, determine correctness. Numbering runs left-to-right within each horizontal strip, then upward. It is adult notation, not an added student requirement.'),H('Hold hints back'),P('First ask a child to show what they tried. Offer a hint only after another attempt. Ask about one edge or one small region rather than supply a full filling. Give an oral or physical explanation full credit when it accounts for all cases.'),PageBreak()]
s += [H('K-1 Problems 2 to 4'),SH('Problem 2'),P('No legal filling has zero all-three cells. The side rules are the hypotheses of the parity proof on page 11. For K-1, preserve time to try and notice that changing one cell can create another. If they want a reason, let the adult mark R-B doors and pair outside entrances: an odd number cannot all be paired with outside exits. Do not present “we tried many” as a proof.'),SH('Problem 3'),P('The maximum is 5 on the nine-cell, three-step board. A witness appears below: bottom-to-top row code RBRB/RYB/RB/Y. Its all-three cells are 2,3,4,7,9. Page 5 proves no legal filling has more than 5. Hint: once a child finds three, ask whether changing the center could help and what that change might destroy.'),SH('Problem 4'),P('Maximum 7. Preserve the six printed labels: bottom RRB, next row YB, top Y. Fill the four inserted centers, by location, lower-left B; central inverted region any of R/B/Y; lower-right Y; top R. There are exactly three maximum fillings, differing only at the central inserted dot. The drawing uses R there.'),pairfig([(3,'RBRB/RYB/RB/Y','Problem 3 maximum 5',None),(2,'RRB/YB/Y','Problem 4 maximum 7',['B','R','Y','R'])],205,190),P('Proof: the original lower-left triangle has corner labels RRY; its three subcells can contribute at most 2, attained by a B center. The original lower-right RBB region contributes at most 2 with Y. The top YBY region contributes at most 2 with R. The central RBY region contributes exactly 1 for any center label: only the edge joining the other two labels makes a three-label subcell. Thus the bound is 2+2+2+1=7, and the displayed filling attains it. Hint: inspect the four original regions separately, while leaving their printed vertices fixed.'),PageBreak()]
s += [H('The three-step minimum and maximum'),P('Grades 2-3 Problem 1 and grades 4-5 Problem 1: the minimum is 1, the maximum 5, and the only attainable counts are 1,3,5. The three exact witnesses below use row codes RRRB/RRB/RB/Y; RRRB/RRY/RB/Y; RBRB/RYB/RB/Y, respectively. The second student page is another copy of Problem 1, not a new problem.'),pairfig([(3,'RRRB/RRB/RB/Y','1 all-three cell',None),(3,'RRRB/RRY/RB/Y','3 all-three cells',None),(3,'RBRB/RYB/RB/Y','5 all-three cells',None)],150,125),H('Why five is the upper bound'),P('Here is a finite structural proof, independent of the enumeration. Rotate the board and rename the three colors together so that the interior center is Y and the opposite bottom corners are R and B. This preserves the problem. Write L,M for the two noncorner bottom labels, left to right. They are each R or B. Write U for the boundary label just below the top corner on the right, and V for the one on the left. U is B or Y; V is R or Y.'),P('Cells 6 and 8, along the left R/Y and right B/Y edges, both lack one required color. The bottom inner cell contributes 1 exactly when L differs from M. The two cells meeting at the lower-left corner region together contribute 1 exactly when L=B; the lower-right pair together contribute 1 exactly when M=R. Each of the two cells along the top inner edge contributes 1 exactly when U=B and V=R.'),P('These groups partition all nine cells: two always-zero cells, one bottom inner cell, two lower-left cells, two lower-right cells, and two top-edge cells. So the total equals a bottom contribution from the table, plus either 0 or 2 from the top-edge pair.'),table([['L','M','Bottom contribution'],['R','R','1'],['R','B','1'],['B','R','3'],['B','B','1']],[80,80,362]),P('The total is therefore 1,3 or 5. The witnesses attain all three. This proves both the upper and lower bounds without appealing to the general theorem. Independent enumeration checks the distribution: 108 legal fillings have 1, 72 have 3, and 12 have 5, among 192 legal fillings.'),P('<b>Held hint:</b> Preserve the best two records, then track what one interior change gains and loses. Ask the upper band whether an even total survives.'),PageBreak()]
rows=[['Cell','Bottom-to-top row code','Cell','Bottom-to-top row code']]
for i in range(1,9):rows.append([i,D['4']['sole'][str(i)],i+8,D['4']['sole'][str(i+8)]])
s += [H('K-1 Problem 5 all sixteen locations'),P('Every one of the 16 small cells can be the only all-three cell. Each table entry is a checked witness for the numbered board below. Read each slash-separated row left-to-right, starting with the bottom row of five vertices, then four, three, two and the top Y. For example RRRRB/RRRB/RRB/RB/Y makes only cell 16 all-three.'),fig(4,None,228),table(rows,[40,221,40,221]),P('The table proves all sixteen locations are possible by explicit construction; there are no other locations because the board has exactly sixteen cells. Do not expect a child to finish sixteen fillings in the hour. A child can keep a record of which cells have worked and return later. Hint: move a boundary between label regions a little at a time, then check that it did not create a second all-three cell. Avoid moving fixed corner letters.'),P('Independent enumeration found 2,920 legal fillings with one all-three cell. The whole four-step distribution is 1,3,5,7,9 all-three cells in 2,920; 6,192; 3,840; 848; 24 fillings, respectively. These checks support this board; they are not a proof for arbitrary triangulations.'),PageBreak()]
s += [H('When the boundary rule changes'),SH('K-1 Problem 6'),P('Four different zero-cell fillings are shown below. Their row codes, in the same order, are RRYB/RRY/RY/Y; RRYB/RRY/YY/Y; RRYB/RYB/RY/Y; RRYB/RYB/YB/Y. Every corner remains fixed. Only the noncorner bottom labels gained permission to use Y. In all four examples the bottom is R-R-Y-B, so it has no R-B door. Hint: try using the newly allowed Y to separate the bottom R and B regions.'),pairfig([(3,D['whole_exception']['zeros'][0],'Filling 1',None),(3,D['whole_exception']['zeros'][1],'Filling 2',None)],150,140),pairfig([(3,D['whole_exception']['zeros'][2],'Filling 3',None),(3,D['whole_exception']['zeros'][3],'Filling 4',None)],150,140),SH('Grades 4-5 Problem 6'),P('A zero-cell witness is RRYBB/RRYB/RRY/RY/Y, shown below. The third bottom label is the starred midpoint Y; every other side rule remains legal. This does not contradict Problem 5 because its R/B-only bottom-side hypothesis is false. The bottom sequence R-R-Y-B-B has no R-B door, so the odd-boundary-door proof no longer applies. There are 208 zero-cell fillings with this one-dot exception, but one verified witness answers the task. Hint: locate the exact sentence in the earlier theorem that the star changes.'),fig(4,D['single_exception']['zeros'][0],125,nums=False),PageBreak()]
s += [H('Grades 2-3 Problem 2 doors and routes'),P('The printed filling is RBRB/RRB/RB/Y. It has 9 doors, including the three bottom edges. In the solution diagram, a short dark blue bar crosses each door. Cell 9 is the only all-three cell. Call the three bottom segments entrances 1,2,3 from left to right.'),fig(3,D['middle_route']['rows'],340,door=True),P('All boundary-started routes, up to reversing the same route, are:<br/>Entrance 1 - cells 1,2,3 - entrance 2.<br/>Entrance 3 - cells 5,4,8,7,9, stopping in cell 9.'),P('Thus entrances 1 and 2 lead back outside; entrance 3 reaches the all-three cell. Starting separately from entrances 1 and 2 traverses the same component in opposite directions. This is why choosing any one entrance need not find an all-three cell. There are no additional internal components on this printed board.'),H('Grades 2-3 Problem 5'),P('For exactly three all-three cells on the four-step board, use the upper printed filling on page 9 of this guide: RRBRB/YBRB/RBB/RB/Y. Cells 2,8,16 are all-three. Its three bottom doors are segments 2,3,4. The boundary routes are segment 2 - cells 3,2, and segment 3 - cells 5,4,10,11,12,6,7 - segment 4. The latter two entrances pair up, but segment 2 ends inside.'),P('No legal filling can have every outside route return outside. Outside-to-outside components consume entrances in pairs, while the number of boundary doors is odd. The internal route between cells 8 and 16 need not be traced for this middle-band problem, which asks only for outside-started routes. Hint: count entrances before tracing, then see which are paired.'),PageBreak()]
s += [H('Grades 4-5 Problem 2 complete door components'),P('The printed row code is RRBRB/YBRB/RBB/RB/Y. All 14 doors are marked. There are three boundary doors, on bottom segments 2,3,4, and three all-three cells, numbered 2,8,16.'),fig(4,D['upper_route']['rows'],365,door=True),P('There are exactly three route components, up to reversal:<br/>1. Bottom segment 2 - cells 3,2. It ends at all-three cell 2.<br/>2. Bottom segment 3 - cells 5,4,10,11,12,6,7 - bottom segment 4. It returns outside.<br/>3. Cells 8,9,13,14,16. It stays inside and joins all-three cells 8 and 16.'),P('The internal component is an open path, not a loop. None of the three components branches. Cell 1 has no door and is not part of a route. A component traced from its other end is the same route in reverse. These lists account for all 14 doors: respectively 2,8 and 4 doors.'),P('The answer to “Can every route from outside return outside?” is no, both on this board and under the legal boundary rules generally. The three entrances here cannot all pair with outside exits. More generally, the proof is on page 11. Hint: after tracing outside components, search for an unused door entirely inside the board.'),PageBreak()]
s += [H('Local fillings and boundary rows'),SH('Problem 3 in both older bands'),P('There are ten classes, with turns and flips identified but color names retained. Repeated letters are allowed. Three monochromatic cases, six two-color cases and one three-color case exhaust all multisets of three labels. The twelve printed triangles include two spare spaces.'),table([['Door count','Complete fillings'],['0','RRR, BBB, YYY, RRY, RYY, BBY, BYY'],['1','RBY'],['2','RRB, RBB']],[90,432]),P('Only RBY has exactly one door. If both R and B occur and Y does not, one label appears twice; each copy connects to the other label, giving two doors. If either R or B is absent, there are none. Three doors are impossible: after putting R and B at two vertices, the third label is R (two doors), B (two doors) or Y (one door). Hint: sort by how many different letters are used, then decide which repeated-letter choice is new.'),SH('Grades 2-3 Problem 4'),P('All five rows must have an odd number of doors, regardless of the empty labels. The rows have 2,3,4,5,6 edges, so the possible counts are respectively {1}, {1,3}, {1,3}, {1,3,5}, {1,3,5}. For a one-door filling, use R until the final B. More generally, any chosen set of k change positions with k odd determines a legal row from R to B, so every listed count is attainable.'),SH('Grades 4-5 Problem 4'),P('Top to bottom: odd, even, odd, even, odd. The rows have 3,4,5,6,7 edges; possible counts are {1,3}; {0,2,4}; {1,3,5}; {0,2,4,6}; {1,3,5,7}. Equal neighboring labels are not doors. Each door switches the current label. An even number of switches returns to the starting label; an odd number ends at the other label. This applies to any length, including a row with no changes.'),P('Sample row fillings, top to bottom, are RRRB; RRRRR; RRRRRB; RRRRRRR; RRRRRRRB. They show the required parity with the fewest doors. To make more, insert a B region inside an R region, adding two changes while leaving the endpoints fixed. Hint: have the child start with an R counter and flip it at each marked door.'),H('The local-to-global bridge'),P('Triangles with two doors pass a path on; triangles with one door stop it; triangles with no doors do not join the door network. This classifies what a route can do before any general proof. A finite route entered from outside cannot get trapped in a disjoint cycle, because every interior transit cell has exactly two doors and provides no branch into a cycle.'),PageBreak()]
s += [H('Why an all-three cell cannot disappear'),SH('Grades 2-3 Problem 6 and grades 4-5 Problem 5'),P('No zero-cell filling is possible on the fan board in middle P6. Upper P5 asks for more: on every finite edge-to-edge triangulation of the large triangle with the stated boundary labels, the number of all-three cells is odd. The cell shapes and sizes need not match. There must be no holes, gaps or unmatched T-junctions.'),P('Along the bottom side, the labels begin R, end B and use only those two letters. The row argument gives an odd number b of boundary doors. Neither other side has a door: the left lacks B and the right lacks R. Every all-three cell has one door; every other cell has zero or two.'),P('Count door incidences, once from each adjoining cell. If T counts all-three cells, U counts two-door cells and I counts interior doors, then T+2U=b+2I. The left side counts by cells. On the right, an interior door is counted twice and a boundary door once. Thus T has the same parity as b, which is odd. In particular T is at least one. This supplies a proof for every filling, not merely the checked examples.'),P('Without symbols, pair the two marks belonging to each interior door and the two doors belonging to each two-door triangle. What remains on one side are the all-three triangles and on the other side the boundary doors. Adding or removing pairs never changes odd/even, so both leftover counts are odd.'),SH('The path version and its important qualification'),P('The finite door network consists of nonbranching paths and possibly closed cycles. Its endpoints are boundary entrances and all-three cells. Paths joining two boundary entrances pair them; paths joining two all-three cells pair those. Each remaining path joins one of each. Since the boundary endpoints are odd, there are an odd number of these mixed paths, and hence an odd total of all-three endpoints. A chosen entrance may return outside, so “start anywhere and you must find one” is not valid.'),P('<b>Held hints:</b> First revisit the ten local types. Then count the boundary changes and ask which endpoints are paired by complete routes. Only after that offer the incidence equation. For K-1, let paired entrances be physical counters; the adult can carry the full argument.'),H('Extensions and fidelity limits'),P('Change a side label and find which part of the proof fails; use the exact exceptions on page 7. Subdivide one little cell by adding an interior vertex and compare old/new parity. This is Sperner’s triangulation lemma, distinct from the antichain theorem with the same name. No claim about actual rent allocation, limits or fixed points follows from this packet alone.'),H('Sources and verification'),P('Francis E. Su, “Rental harmony: Sperner’s lemma in fair division,” <i>American Mathematical Monthly</i> 106 (1999), 930-942, author PDF pp. 2-5, especially the door-path and incidence arguments: https://math.hmc.edu/su/wp-content/uploads/sites/10/2019/06/Rental-harmony.pdf. Explicit two-dimensional statement: Harvey Mudd Math Fun Facts, https://math.hmc.edu/funfacts/sperners-lemma/. The diagrams, exact instances and row-code keys here were independently computed for the final packet.',True),P('Teaching evidence: Rozhkovskaya, <i>Math Circles for Elementary School Students</i>, “Introduction: Berkeley 2009,” describes individual adult support. This teaching menu is unpiloted. Independent checking rebuilt cells by geometric adjacency, checked area and shared-edge incidences, and verified distributions, witnesses and door routes. Editable checks accompany this guide. Two door examples were added.',True)]
# Mathematical assertions on the explicit maximum and all authored witnesses.
assert tri(mesh(3)[2],rowcolor('RBRB/RYB/RB/Y'))==[2,3,4,7,9]
